// asteroids with radial gradient
asteroids.forEach(a => {
  const grad = ctx.createRadialGradient(a.x, a.y, a.r * 0.2, a.x, a.y, a.r);
  grad.addColorStop(0, '#bbb');
  grad.addColorStop(1, '#555');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
  ctx.fill();
  // subtle outline
  ctx.strokeStyle = '#222';
  ctx.lineWidth = 1;
  ctx.stroke();
});

